async home(screen: PilotUiPayload["screen"] = "m01", selectedPlanId?: string | null, sessionId?: string): Promise<PilotUiPayload> {
    const [plans, sessionContext] = await Promise.all([
      this.repository.listPlans(),
      this.repository.getSessionContext(sessionId),
    ]);
    const activeSession = sessionContext.session?.status === "active" ? sessionContext.session : null;
    const sessionScreen = ["learning_active", "review_summary", "review_evidence", "stop_confirm"].includes(screen);
    const selectedPlan = selectedPlanId
      && !sessionScreen ? await this.repository.getPlan(selectedPlanId)
      : sessionScreen || activeSession ? sessionContext.plan
      : plans.length === 1 ? plans[0]! : null;
    if (selectedPlanId && !selectedPlan && !sessionScreen) {
      throw new Error("선택한 Plan을 찾을 수 없어요. 내 Plan 목록에서 다시 선택해주세요.");
    }
    const reviews = await this.repository.listReviews(selectedPlan?.plan_id);
    return PilotUiPayloadSchema.parse({
      schema_version: PilotSchemaVersion,
      screen: screen === "learning_active" && !activeSession ? "free_study"
        : ["plan_detail", "plan_structure", "learning_scope", "material_add", "material_updated"].includes(screen) && !selectedPlan ? "my_plans" : screen,
      plans,
      selected_plan: selectedPlan,
      active_session: activeSession,
      review_summary: sessionScreen || activeSession ? reviews.find(r => r.session_id === sessionContext.session?.session_id) ?? null : reviews[0] ?? null,
      notice: null,
      session_context: sessionContext,
    });
  }

async getPlanContext(planId?: string) {
    if (planId) {
      const plan = await this.repository.getPlan(planId);
      if (!plan) throw new Error("선택한 Plan을 찾을 수 없어요.");
      return plan;
    }
    const [activeSession, plans] = await Promise.all([
      this.repository.getActiveSession(),
      this.repository.listPlans(),
    ]);
    if (activeSession?.status === "active" && activeSession.plan_id) {
      const activePlan = await this.repository.getPlan(activeSession.plan_id);
      if (activePlan) return activePlan;
    }
    if (plans.length !== 1) throw new Error("대상 Plan을 먼저 선택해주세요.");
    return plans[0];
  }

submitFeedback(input: unknown) {
    return this.repository.submitFeedback(
      SubmitPilotFeedbackInputSchema.parse(input) as SubmitPilotFeedbackInput,
    );
  }

async getLearningStrategy(filters: { plan_id?: string; session_id?: string } = {}) {
    const [candidates, learningInsights] = await Promise.all([
      this.repository.listStateCandidates(),
      this.repository.listLearningInsights(filters),
    ]);
    // Session review must not borrow a later candidate from another session.
    const scopedCandidates = filters.session_id ? [] : candidates;
    const grouped = new Map<string, typeof candidates>();
    for (const candidate of scopedCandidates) {
      if (filters.plan_id && candidate.plan_id !== filters.plan_id) continue;
      const key = `${candidate.plan_id ?? "unknown"}:${candidate.concept_node_id}`;
      const list = grouped.get(key) ?? [];
      list.push(candidate);
      grouped.set(key, list);
    }
    return {
      learning_insights: learningInsights,
      state_candidates: filters.plan_id
        ? scopedCandidates.filter((candidate) => candidate.plan_id === filters.plan_id)
        : scopedCandidates,
      intervention_suggestions: [...grouped.values()].flatMap((states) => suggestInterventions(states)),
      notice: "검증 전 후보값이며 자동 개입에 사용하지 않습니다.",
    };
  }
}

submitFeedback(input: SubmitPilotFeedbackInput): Promise<PilotFeedbackReceipt>;
