create function studymeta_api.prepare_my_pilot_input(p_input jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare learner uuid; saved studymeta_v2.pilot_input_contexts%rowtype;
begin
  learner:=studymeta_v2.current_learner_id();
  if learner is null then raise exception 'authenticated learner required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtext(learner::text),hashtext('pilot-input'));
  delete from studymeta_v2.pilot_input_contexts where learner_id=learner and expires_at<now();
  if coalesce(p_input->>'kind','') not in ('plan','material') or length(p_input::text)>100000 then
    raise exception 'valid bounded input required' using errcode='22023';
  end if;
  if p_input->>'plan_id' is not null and not exists(select 1 from studymeta_v2.study_plans where learner_id=learner and id=(p_input->>'plan_id')::uuid) then
    raise exception 'plan not found' using errcode='22023';
  end if;
  select * into saved from studymeta_v2.pilot_input_contexts where learner_id=learner and request_id=(p_input->>'request_id')::uuid;
  if saved.request_id is not null then
    if saved.payload<>p_input then raise exception 'idempotency key reused with different input' using errcode='22023'; end if;
    if saved.status<>'ready' then raise exception 'input request is no longer active' using errcode='22023'; end if;
  else
    if exists(select 1 from studymeta_v2.pilot_input_contexts where learner_id=learner and status='ready') then
      raise exception 'another input request is pending' using errcode='22023';
    end if;
    insert into studymeta_v2.pilot_input_contexts(learner_id,request_id,payload,status)
    values(learner,(p_input->>'request_id')::uuid,p_input,'ready') returning * into saved;
  end if;
  return jsonb_build_object('request_id',saved.request_id,'status',saved.status,
    'material_status',case when saved.payload->'material'='null'::jsonb then 'none' else 'readable' end,'expires_at',saved.expires_at);
end $$;

create function studymeta_api.cancel_my_pilot_input(p_request_id uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare saved studymeta_v2.pilot_input_contexts%rowtype;
begin
  update studymeta_v2.pilot_input_contexts set status='cancelled' where learner_id=studymeta_v2.current_learner_id() and request_id=p_request_id and status in ('ready','cancelled') returning * into saved;
  if saved.request_id is null then raise exception 'input already saved or not found' using errcode='22023'; end if;
  return jsonb_build_object('request_id',saved.request_id,'status','cancelled',
    'material_status',case when saved.payload->'material'='null'::jsonb then 'none' else 'readable' end,'expires_at',saved.expires_at);
end $$;

create or replace function studymeta_api.get_my_pilot_session_context(p_session_id uuid default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare learner uuid; s studymeta_v2.sessions%rowtype; link studymeta_v2.pilot_session_plans%rowtype; plan studymeta_v2.study_plans%rowtype;
begin
  learner:=studymeta_v2.current_learner_id();
  if learner is null then raise exception 'authenticated learner required' using errcode='42501'; end if;
  select sessions.* into s from studymeta_v2.sessions sessions join studymeta_v2.pilot_session_plans l on l.learner_id=sessions.learner_id and l.session_id=sessions.id
    where sessions.learner_id=learner and (p_session_id is null or sessions.id=p_session_id)
    order by (sessions.status='active') desc,sessions.started_at desc limit 1;
  if p_session_id is not null and s.id is null then raise exception 'learner-owned session required' using errcode='22023'; end if;
  select * into link from studymeta_v2.pilot_session_plans where learner_id=learner and session_id=s.id;
  select * into plan from studymeta_v2.study_plans where learner_id=learner and id=link.plan_id;
  return jsonb_build_object('session',case when s.id is null then null else studymeta_v2.pilot_session_json(s,link) end,
    'plan',case when plan.id is null then null else studymeta_v2.pilot_plan_json(plan) end,'server_time',now(),
    'record_count',(select count(*) from studymeta_v2.pilot_learning_events where learner_id=learner and session_id=s.id),
    'pending_event_ids',coalesce((select jsonb_agg(e.id order by e.recorded_at) from studymeta_v2.pilot_learning_events e join studymeta_v2.pilot_event_processing p on p.learner_id=e.learner_id and p.event_id=e.id
      where e.learner_id=learner and e.session_id=s.id and p.status='pending'),'[]'::jsonb));
end $$;

create or replace function studymeta_api.update_my_session_goal(p_request jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare learner uuid; s studymeta_v2.sessions%rowtype; link studymeta_v2.pilot_session_plans%rowtype; prior jsonb;
begin
  learner:=studymeta_v2.current_learner_id();
  select * into s from studymeta_v2.sessions where learner_id=learner and id=(p_request->>'session_id')::uuid for update;
  select * into link from studymeta_v2.pilot_session_plans where learner_id=learner and session_id=s.id;
  if link.session_id is null then raise exception 'learner-owned session required' using errcode='22023'; end if;
  select entry into prior from jsonb_array_elements(link.goal_history) entry where entry->>'idempotency_key'=p_request->>'idempotency_key';
  if prior is not null then
    if prior->'goal' is distinct from p_request->'session_goal' or prior->>'reason' is distinct from p_request->>'reason' then
      raise exception 'idempotency key reused with different goal payload' using errcode='22023';
    end if;
    return studymeta_v2.pilot_session_json(s,link);
  end if;
  if s.status<>'active' then raise exception 'active learner-owned session required' using errcode='22023'; end if;
  update studymeta_v2.pilot_session_plans set session_goal=nullif(btrim(p_request->>'session_goal'),''),
    goal_history=goal_history||jsonb_build_array(jsonb_build_object('goal',p_request->'session_goal','changed_at',now(),'reason',p_request->>'reason','idempotency_key',p_request->>'idempotency_key'))
    where learner_id=learner and session_id=s.id returning * into link;
  return studymeta_v2.pilot_session_json(s,link);
end $$;

create or replace function studymeta_api.retry_my_pilot_event(p_event_id uuid)
