create function studymeta_api.save_my_study_plan(p_plan jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare learner uuid:=studymeta_v2.current_learner_id(); source_input jsonb;
begin
  if not exists(select 1 from studymeta_v2.pilot_plan_save_requests where learner_id=learner and idempotency_key=p_plan->>'idempotency_key') then
    if p_plan->>'input_request_id' is not null then
      select payload into source_input from studymeta_v2.pilot_input_contexts where learner_id=learner and request_id=(p_plan->>'input_request_id')::uuid;
      if source_input is not null and (source_input->>'course_title' is distinct from p_plan->>'course_title'
        or source_input->>'exam_date' is distinct from p_plan->>'exam_date'
        or source_input->>'scope_text' is distinct from p_plan->>'scope_text') then
        raise exception 'input course, date or scope mismatched' using errcode='22023';
      end if;
      perform studymeta_v2.consume_pilot_input((p_plan->>'input_request_id')::uuid,'plan',(p_plan->>'plan_id')::uuid);
    elsif exists(select 1 from studymeta_v2.pilot_input_contexts where learner_id=learner and status='ready' and expires_at>now()) then
      raise exception 'pending input_request_id required' using errcode='22023';
    end if;
  end if;
  return studymeta_v2.save_my_study_plan(p_plan);
end $$;

