create or replace function studymeta_api.start_my_learning_session(p_request jsonb)
returns jsonb language plpgsql security definer set search_path = pg_catalog as $$
declare learner uuid; s studymeta_v2.sessions%rowtype; link studymeta_v2.pilot_session_plans%rowtype;
begin
  learner:=studymeta_v2.current_learner_id();
  if learner is null then raise exception 'authenticated learner required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtext(learner::text),hashtext('pilot-session'));
  select * into link from studymeta_v2.pilot_session_plans
   where learner_id=learner and idempotency_key=p_request->>'idempotency_key';
  if link.session_id is not null then
    if link.plan_id is distinct from (p_request->>'plan_id')::uuid or to_jsonb(link.focus_node_ids) is distinct from p_request->'focus_node_ids'
      or link.goal_history#>>'{0,goal}' is distinct from nullif(btrim(p_request->>'session_goal'),'') then
      raise exception 'idempotency key reused with different session payload' using errcode='22023';
    end if;
    select * into s from studymeta_v2.sessions where learner_id=learner and id=link.session_id;
    return studymeta_v2.pilot_session_json(s,link);
  end if;
  if nullif(p_request->>'plan_id','') is not null then
  if not exists(select 1 from studymeta_v2.study_plans where learner_id=learner and id=(p_request->>'plan_id')::uuid and status='confirmed') then
    raise exception 'confirmed plan required' using errcode='22023';
  end if;
  if jsonb_typeof(p_request->'focus_node_ids')<>'array' or jsonb_array_length(p_request->'focus_node_ids')=0
     or exists (
       select 1 from jsonb_array_elements_text(p_request->'focus_node_ids') requested(node_id)
       where not exists (
         select 1 from studymeta_v2.study_plans p,jsonb_array_elements(p.nodes) node
         where p.learner_id=learner and p.id=(p_request->>'plan_id')::uuid
           and node->>'kind'='concept' and node->>'node_id'=requested.node_id
       )
     ) then raise exception 'focus must contain learner-owned concept nodes' using errcode='22023'; end if;
  elsif coalesce(p_request->'focus_node_ids','[]'::jsonb)<>'[]'::jsonb then
    raise exception 'free study cannot contain plan concept nodes' using errcode='22023';
  end if;
  update studymeta_v2.sessions set status='idle',end_reason='changed_by_new_session'
   where learner_id=learner and status='active';
  insert into studymeta_v2.sessions(learner_id,status,active_focus,started_at,last_resumed_at,idle_deadline_at,timeout_policy_version)
  values(learner,'active',jsonb_build_object('focus_node_ids',p_request->'focus_node_ids'),now(),now(),now()+interval '24 hours','pilot-v1')
  returning * into s;
  insert into studymeta_v2.pilot_session_plans(learner_id,session_id,plan_id,focus_node_ids,idempotency_key,session_goal,goal_history)
  values(learner,s.id,(p_request->>'plan_id')::uuid,array(select jsonb_array_elements_text(p_request->'focus_node_ids')),p_request->>'idempotency_key',nullif(btrim(p_request->>'session_goal'),''),jsonb_build_array(jsonb_build_object('goal',nullif(btrim(p_request->>'session_goal'),''),'changed_at',now(),'reason','시작 목표')))
  returning * into link;
  return studymeta_v2.pilot_session_json(s,link);
end $$;

create or replace function studymeta_api.record_my_pilot_learning_event(p_event jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare learner uuid; link studymeta_v2.pilot_session_plans%rowtype; s studymeta_v2.sessions%rowtype;
  saved studymeta_v2.pilot_learning_events%rowtype; event_time timestamptz;
begin
  learner:=studymeta_v2.current_learner_id();
  if learner is null then raise exception 'authenticated learner required' using errcode='42501'; end if;
  if coalesce(length(btrim(p_event->>'idempotency_key')),0)<8 then raise exception 'event idempotency key required' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtext(learner::text),hashtext(p_event->>'idempotency_key'));
  select * into saved from studymeta_v2.pilot_learning_events where learner_id=learner and idempotency_key=p_event->>'idempotency_key';
  if saved.id is not null then
    if saved.session_id is distinct from (p_event->>'session_id')::uuid
      or saved.concept_node_id is distinct from p_event->>'concept_node_id'
      or saved.event_type is distinct from p_event->>'event_type'
      or (p_event->>'occurred_at' is not null and saved.occurred_at is distinct from (p_event->>'occurred_at')::timestamptz)
      or saved.observation is distinct from p_event->'observation' then
      raise exception 'idempotency key reused with different event payload' using errcode='22023';
    end if;
    perform studymeta_v2.process_pilot_event(saved.id);
    return studymeta_v2.pilot_event_receipt(saved,true);
  end if;
  select * into link from studymeta_v2.pilot_session_plans where learner_id=learner and session_id=(p_event->>'session_id')::uuid;
  select * into s from studymeta_v2.sessions where learner_id=learner and id=link.session_id for update;
  if link.session_id is null or s.status<>'active' then raise exception 'active learner-owned session required' using errcode='22023'; end if;
  event_time:=coalesce((p_event->>'occurred_at')::timestamptz,now());
  if event_time<s.started_at-interval '5 minutes' or event_time>now()+interval '5 minutes' then
    raise exception 'event time is outside the active session window' using errcode='22023';
  end if;
  if link.plan_id is null and p_event->>'concept_node_id' is not null then
    raise exception 'free study cannot contain plan concept nodes' using errcode='22023';
  end if;
  if link.plan_id is not null and p_event->>'concept_node_id' is not null and not (
    p_event->>'concept_node_id'=any(link.focus_node_ids) and exists(select 1 from studymeta_v2.study_plans p,jsonb_array_elements(p.nodes) node
      where p.learner_id=learner and p.id=link.plan_id and node->>'kind'='concept' and node->>'node_id'=p_event->>'concept_node_id')) then
    raise exception 'concept node is not in the selected focus' using errcode='22023';
  end if;
  insert into studymeta_v2.pilot_learning_events(learner_id,session_id,plan_id,concept_node_id,event_type,occurred_at,observation,idempotency_key,source)
  values(learner,link.session_id,link.plan_id,p_event->>'concept_node_id',p_event->>'event_type',event_time,p_event->'observation',p_event->>'idempotency_key',coalesce(p_event->>'source','other')) returning * into saved;
  insert into studymeta_v2.pilot_event_processing(learner_id,event_id,status) values(learner,saved.id,'pending');
  update studymeta_v2.sessions set last_learning_event_at=event_time,session_revision=session_revision+1 where learner_id=learner and id=link.session_id;
  perform studymeta_v2.process_pilot_event(saved.id);
  return studymeta_v2.pilot_event_receipt(saved,false);
end $$;

create or replace function studymeta_api.stop_my_learning_session(p_request jsonb)
returns jsonb language plpgsql security definer set search_path = pg_catalog as $$
declare learner uuid; s studymeta_v2.sessions%rowtype; link studymeta_v2.pilot_session_plans%rowtype; action text;
begin
  learner:=studymeta_v2.current_learner_id(); action:=p_request->>'action';
  select * into link from studymeta_v2.pilot_session_plans where learner_id=learner and session_id=(p_request->>'session_id')::uuid;
  select * into s from studymeta_v2.sessions where learner_id=learner and id=link.session_id for update;
  if link.session_id is null or action not in ('review','stop','change') then
    raise exception 'active learner-owned session action required' using errcode='22023';
  end if;
  if s.status='completed' or (s.status='idle' and action='change') then return studymeta_v2.pilot_session_json(s,link); end if;
  update studymeta_v2.sessions set
    status=case when action='stop' then 'completed' when action='change' then 'idle' else s.status end,
    ended_at=case when action='stop' then coalesce(ended_at,now()) else ended_at end,
    end_reason=case when action='review' then end_reason else action end,
    summary_status=case when action='review' then 'pending' else summary_status end,
    session_revision=session_revision+1
  where learner_id=learner and id=link.session_id returning * into s;
  return studymeta_v2.pilot_session_json(s,link);
end $$;

create or replace function studymeta_api.save_my_session_review(p_review jsonb)
returns jsonb language plpgsql security definer set search_path = pg_catalog as $$
declare learner uuid; saved studymeta_v2.pilot_session_reviews%rowtype; plan uuid;
begin
  learner:=studymeta_v2.current_learner_id();
  select plan_id into plan from studymeta_v2.pilot_session_plans
   where learner_id=learner and session_id=(p_review->>'session_id')::uuid;
  if not found then raise exception 'learner-owned session required' using errcode='22023'; end if;
  if not exists(select 1 from studymeta_v2.pilot_learning_events where learner_id=learner and session_id=(p_review->>'session_id')::uuid) then
    raise exception 'at least one recorded learning Event is required for a review' using errcode='22023';
  end if;
  insert into studymeta_v2.pilot_session_reviews(learner_id,session_id,strong_points,difficult_points,review_points,next_step)
  values(learner,(p_review->>'session_id')::uuid,p_review->'strong_points',p_review->'difficult_points',p_review->'review_points',p_review->>'next_step')
  on conflict(learner_id,session_id) do update set strong_points=excluded.strong_points,difficult_points=excluded.difficult_points,review_points=excluded.review_points,next_step=excluded.next_step
  returning * into saved;
  update studymeta_v2.sessions set summary_status='final' where learner_id=learner and id=saved.session_id;
  return jsonb_build_object('summary_id',saved.id,'session_id',saved.session_id,'plan_id',plan,
    'strong_points',saved.strong_points,'difficult_points',saved.difficult_points,'review_points',saved.review_points,
    'next_step',saved.next_step,'created_at',saved.created_at,'saved',true);
end $$;

create or replace function studymeta_api.delete_my_study_plan(p_request jsonb)
returns jsonb language plpgsql security definer set search_path = pg_catalog as $$
declare learner uuid; target studymeta_v2.study_plans%rowtype; session_ids uuid[];
begin
  learner:=studymeta_v2.current_learner_id();
  select * into target from studymeta_v2.study_plans
   where learner_id=learner and id=(p_request->>'plan_id')::uuid for update;
  if target.id is null or target.title <> p_request->>'confirm_title' then
    raise exception 'plan title confirmation failed' using errcode='22023';
  end if;
  perform set_config('studymeta.pilot_erase_authorized','on',true);
  select array_agg(session_id) into session_ids from studymeta_v2.pilot_session_plans
   where learner_id=learner and plan_id=target.id;
  delete from studymeta_v2.pilot_state_candidates where learner_id=learner and plan_id=target.id;
  delete from studymeta_v2.pilot_learning_events where learner_id=learner and plan_id=target.id;
  delete from studymeta_v2.sessions where learner_id=learner and id=any(coalesce(session_ids,'{}'::uuid[]));
  delete from studymeta_v2.study_plans where learner_id=learner and id=target.id;
  return jsonb_build_object('deleted',true,'plan_id',target.id);
end $$;

create or replace function studymeta_api.submit_my_pilot_feedback(p_feedback jsonb)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  learner uuid;
  body text;
  request_key text;
  context jsonb;
  saved studymeta_v2.pilot_feedback%rowtype;
begin
  learner := studymeta_v2.current_learner_id();
  body := btrim(coalesce(p_feedback->>'feedback_text', ''));
  request_key := btrim(coalesce(p_feedback->>'idempotency_key', ''));
  context := case
    when p_feedback->'screen_context' is null or p_feedback->'screen_context' = 'null'::jsonb then null
    else p_feedback->'screen_context'
  end;

  if char_length(body) < 1 or char_length(body) > 10000 then
    raise exception 'feedback_text must contain 1 to 10000 characters' using errcode = '22023';
  end if;
  if char_length(request_key) < 8 or char_length(request_key) > 200 then
    raise exception 'invalid feedback idempotency key' using errcode = '22023';
  end if;
  if context is not null then
    if jsonb_typeof(context) <> 'object'
      or coalesce(context->>'screen', '') not in (
        'm01','mc01','my_plans','plan_detail','plan_input','plan_building','plan_structure',
        'learning_scope','learning_active','my_info','review_summary','review_full','review_evidence',
        'stop_confirm','material_add','material_analyzing','material_updated','notes','free_study','plan_date','plan_material'
      )
      or coalesce(context->>'app_version', '') = ''
      or char_length(context->>'app_version') > 40
      or coalesce(context->>'device_type', '') not in ('mobile', 'desktop')
      or (context->'plan_id' is not null and context->'plan_id' <> 'null'::jsonb and jsonb_typeof(context->'plan_id') <> 'string')
      or (context->'session_id' is not null and context->'session_id' <> 'null'::jsonb and jsonb_typeof(context->'session_id') <> 'string')
      or exists (
        select 1 from jsonb_object_keys(context) as key
        where key not in ('screen', 'plan_id', 'session_id', 'app_version', 'device_type')
      )
    then
      raise exception 'invalid feedback screen context' using errcode = '22023';
    end if;
    if context->>'plan_id' is not null then perform (context->>'plan_id')::uuid; end if;
    if context->>'session_id' is not null then perform (context->>'session_id')::uuid; end if;
  end if;

  select * into saved
  from studymeta_v2.pilot_feedback
  where learner_id = learner and idempotency_key = request_key;

  if saved.id is not null then
    if saved.feedback_text <> body or saved.screen_context is distinct from context then
      raise exception 'feedback idempotency key already used with different input' using errcode = '23505';
    end if;
    return jsonb_build_object(
      'feedback_id', saved.id,
      'duplicate', true,
      'submitted_at', saved.submitted_at,
      'saved', true,
      'message', '이미 같은 피드백이 안전하게 저장되어 있어요.'
    );
  end if;

  insert into studymeta_v2.pilot_feedback (
    learner_id, feedback_text, screen_context, idempotency_key
  ) values (
    learner, body, context, request_key
  ) returning * into saved;

  return jsonb_build_object(
    'feedback_id', saved.id,
    'duplicate', false,
    'submitted_at', saved.submitted_at,
    'saved', true,
    'message', '피드백을 저장했어요. 고마워요.'
  );
end
$$;

