server.registerTool(
    "stop_or_change_study",
    {
      title: "학습 중단 또는 정리 전환",
      description: "활성 세션에서 사용자가 ‘정리해줘’, ‘오늘은 여기까지’, ‘그만할래’, ‘다른 개념으로 바꿀래’처럼 정리·중단·변경 의사를 분명히 보일 때 호출합니다. review는 세션을 유지한 채 정리 단계로 전환하고, change는 잠시 멈추며, stop만 완료 처리합니다. 이 도구는 저장 결과와 알맞은 UI를 함께 반환합니다. stop이면 ‘여기까지 저장됐어요’ 완료 카드가 이미 포함되므로 render_studymeta_screen을 같은 응답에서 호출하지 마세요. 성공 전에는 저장 또는 중단됐다고 말하지 마세요.",
      inputSchema: StopSessionInputSchema,
      outputSchema: PilotUiPayloadSchema,
      annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: true, openWorldHint: false },
      _meta: renderMeta,
    },
    async (input) => {
      try {
        const session = await services.pilotService.stopSession(input);
        const screen = input.action === "stop"
          ? "stop_confirm"
          : input.action === "review"
            ? "review_summary"
            : "learning_scope";
        const projected = await services.pilotService.home(screen, session.plan_id, session.session_id);
        const output = input.action === "stop"
          ? PilotUiPayloadSchema.parse({ ...projected, active_session: null, notice: `학습을 마쳤어요. 저장된 학습 기록 ${projected.session_context?.record_count ?? 0}건` })
          : projected;
        return {
          content: [{
            type: "text" as const,
            text: input.action === "stop"
              ? "세션 종료를 확인했어요. 카드의 실제 저장 건수만 안내하고 다른 UI 도구를 호출하지 마세요."
              : "학습 상태를 저장했고 다음 화면을 표시했습니다. 다른 UI 도구를 호출하지 마세요.",
          }],
          structuredContent: output,
        };
      }
      catch (error) { return errorResult(error); }
    },
  );

